CREATE TABLE IF NOT EXISTS configurations(id text PRIMARY KEY, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS collection_runs(id text PRIMARY KEY, configuration_id text NOT NULL REFERENCES configurations(id), status text NOT NULL, summary jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE IF NOT EXISTS inventory(id text PRIMARY KEY, collection_id text NOT NULL REFERENCES collection_runs(id), source_id text NOT NULL, object_key text NOT NULL, kind text NOT NULL, status text NOT NULL, details jsonb NOT NULL DEFAULT '{}', UNIQUE(collection_id,source_id,object_key,kind));
CREATE TABLE IF NOT EXISTS evidence(id text PRIMARY KEY, collection_id text NOT NULL REFERENCES collection_runs(id), source_id text NOT NULL, object_id text NOT NULL, revision text NOT NULL, kind text NOT NULL, title text NOT NULL, url text NOT NULL, occurred_at timestamptz, actors jsonb NOT NULL, raw_hash text NOT NULL, body text NOT NULL, metadata jsonb NOT NULL, UNIQUE(collection_id,source_id,object_id,revision,kind));
CREATE INDEX IF NOT EXISTS evidence_collection ON evidence(collection_id);
ALTER TABLE evidence ADD COLUMN IF NOT EXISTS captured_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS evaluation_runs(id text PRIMARY KEY, collection_id text NOT NULL REFERENCES collection_runs(id), configuration_id text NOT NULL REFERENCES configurations(id), model jsonb NOT NULL, status text NOT NULL, parent_run_id text REFERENCES evaluation_runs(id), corrections jsonb NOT NULL DEFAULT '[]', summary jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE IF NOT EXISTS assessments(id text PRIMARY KEY, evaluation_id text NOT NULL REFERENCES evaluation_runs(id), evidence_id text NOT NULL REFERENCES evidence(id), output jsonb NOT NULL, UNIQUE(evaluation_id,evidence_id));
CREATE TABLE IF NOT EXISTS portfolios(evaluation_id text NOT NULL REFERENCES evaluation_runs(id), person_id text NOT NULL, output jsonb NOT NULL, PRIMARY KEY(evaluation_id,person_id));
CREATE TABLE IF NOT EXISTS contribution_cases(id text PRIMARY KEY, evaluation_id text NOT NULL REFERENCES evaluation_runs(id), output jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS ai_traces(id text PRIMARY KEY, evaluation_id text NOT NULL REFERENCES evaluation_runs(id), stage text NOT NULL, input_hash text NOT NULL, input_ref text NOT NULL, response_ref text, session_id text, requested_model jsonb NOT NULL, observed_model jsonb, runtime_version text, status text NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS corrections(id text PRIMARY KEY, evaluation_id text NOT NULL REFERENCES evaluation_runs(id), type text NOT NULL, target_id text NOT NULL, before_value jsonb NOT NULL, after_value jsonb NOT NULL, reason text NOT NULL, evidence_ids jsonb NOT NULL, actor text NOT NULL, successor_run_id text REFERENCES evaluation_runs(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports(id text PRIMARY KEY, evaluation_id text NOT NULL REFERENCES evaluation_runs(id), status text NOT NULL, decisions jsonb NOT NULL DEFAULT '{}', actor text NOT NULL, reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS reports_one_per_evaluation ON reports(evaluation_id);
CREATE TABLE IF NOT EXISTS jobs(id text PRIMARY KEY, kind text NOT NULL, target_id text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, lease_owner text, lease_until timestamptz, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,target_id));
CREATE TABLE IF NOT EXISTS audit_events(id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, target_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY, username text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS model_checks(id text PRIMARY KEY, requested_model jsonb NOT NULL, observed_model jsonb, runtime_version text, status text NOT NULL, error text, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS grounding_reviews(evaluation_id text NOT NULL REFERENCES evaluation_runs(id), person_id text NOT NULL, portfolio_hash text NOT NULL, reviewed_summary text NOT NULL, reason text NOT NULL, citations jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(evaluation_id,person_id), FOREIGN KEY(evaluation_id,person_id) REFERENCES portfolios(evaluation_id,person_id));
CREATE TABLE IF NOT EXISTS management_sources(id text PRIMARY KEY, collection_id text NOT NULL REFERENCES collection_runs(id), repository_id text NOT NULL, title text NOT NULL, url text NOT NULL, raw_hash text NOT NULL, body text NOT NULL, metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS management_snapshots(evaluation_id text NOT NULL REFERENCES evaluation_runs(id), repository_id text NOT NULL, output jsonb NOT NULL, PRIMARY KEY(evaluation_id,repository_id));
CREATE TABLE IF NOT EXISTS repository_profiles(evaluation_id text NOT NULL REFERENCES evaluation_runs(id), repository_id text NOT NULL, output jsonb NOT NULL, PRIMARY KEY(evaluation_id,repository_id));
CREATE TABLE IF NOT EXISTS feature_assignments(evaluation_id text NOT NULL REFERENCES evaluation_runs(id), case_id text NOT NULL, repository_id text NOT NULL, output jsonb NOT NULL, PRIMARY KEY(evaluation_id,case_id));
CREATE TABLE IF NOT EXISTS feature_reports(evaluation_id text NOT NULL REFERENCES evaluation_runs(id), feature_id text NOT NULL, repository_id text NOT NULL, output jsonb NOT NULL, PRIMARY KEY(evaluation_id,feature_id));
CREATE TABLE IF NOT EXISTS feature_plans(evaluation_id text NOT NULL REFERENCES evaluation_runs(id), initiative_id text NOT NULL, repository_id text NOT NULL, output jsonb NOT NULL, PRIMARY KEY(evaluation_id,initiative_id));
CREATE TABLE IF NOT EXISTS feature_plan_groups(evaluation_id text NOT NULL REFERENCES evaluation_runs(id), group_id text NOT NULL, repository_id text NOT NULL, output jsonb NOT NULL, PRIMARY KEY(evaluation_id,group_id));
ALTER TABLE ai_traces ADD COLUMN IF NOT EXISTS reused_from_trace text REFERENCES ai_traces(id);
CREATE TABLE IF NOT EXISTS management_digest_parts(evaluation_id text NOT NULL REFERENCES evaluation_runs(id),part_id text NOT NULL,repository_id text NOT NULL,output jsonb NOT NULL,PRIMARY KEY(evaluation_id,part_id));
CREATE TABLE IF NOT EXISTS management_case_facts(evaluation_id text NOT NULL REFERENCES evaluation_runs(id),case_id text NOT NULL,repository_id text NOT NULL,output jsonb NOT NULL,PRIMARY KEY(evaluation_id,case_id));

ALTER TABLE ai_traces ADD COLUMN IF NOT EXISTS reuse_reason text;

CREATE TABLE IF NOT EXISTS personal_feature_reports(evaluation_id text NOT NULL REFERENCES evaluation_runs(id),person_id text NOT NULL,feature_id text NOT NULL,output jsonb NOT NULL,PRIMARY KEY(evaluation_id,person_id,feature_id));
CREATE TABLE IF NOT EXISTS executive_briefs(evaluation_id text NOT NULL REFERENCES evaluation_runs(id),kind text NOT NULL CHECK(kind IN ('repository','member')),subject_id text NOT NULL,revision text NOT NULL,output jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(evaluation_id,kind,subject_id,revision));
